import {createSelector} from 'reselect'

import {getAgentPoolsTree, getAgentSelectionPools} from '../../AgentsPages.selectors'

export const getAllAgentsTab = createSelector(
  [getAgentSelectionPools, getAgentPoolsTree],
  (selectionPools, agentPools) => [selectionPools.detached, ...agentPools],
)
