import {H2} from '@jetbrains/ring-ui-built/components/heading/heading'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import * as React from 'react'

import type {HintId} from '../../../../packages/Hints/Hints.types'

import styles from './ExpandablePanel.module.css'

type ExpandablePanelProps = {
  className?: string
  headerClassName?: string
  headerToggleClassName?: string
  headingClassName?: string
  subheadingClassName?: string
  contentClassName?: string
  heading: React.ReactNode
  subheading?: React.ReactNode
  content?: React.ReactNode
  expanded: boolean
  defaultExpanded?: boolean
  onToggle?: () => unknown
  hintId?: HintId | null | undefined
}

function ExpandablePanel(
  {
    className,
    headerClassName,
    headerToggleClassName,
    headingClassName,
    subheadingClassName,
    contentClassName,
    heading,
    subheading,
    content,
    expanded: controlledExpanded,
    onToggle: controlledOnToggle,
    defaultExpanded = true,
    hintId,
  }: ExpandablePanelProps,
  ref: React.Ref<HTMLDivElement>,
) {
  const [ownExpanded, setOwnExpanded] = React.useState(defaultExpanded)
  const ownOnToggle = React.useCallback(
    () => setOwnExpanded(!ownExpanded),
    [ownExpanded, setOwnExpanded],
  )
  const empty = content == null
  const onToggle = controlledOnToggle ?? ownOnToggle
  const expanded =
    (!empty && (controlledOnToggle == null ? ownExpanded : controlledExpanded)) || false
  const headerElement = React.useMemo(
    () => (
      <H2 className={classNames(styles.header, headerClassName)}>
        <div
          data-hint-container-id={hintId}
          className={classNames(headerToggleClassName, styles.headerToggle, {
            [styles.disabled]: empty,
          })}
          // there's an IconButton child
          role="presentation"
          onClick={!empty ? onToggle : undefined}
        >
          <IconButton
            disabled={empty}
            className={classNames(styles.chevronIcon, {
              [styles.disabledIcon]: empty,
            })}
            iconClassName={styles.chevronIconWrapper}
            title={expanded ? 'Collapse section' : 'Expand section'}
            icon={expanded ? 'chevron-down' : 'chevron-right'}
          />
          <span className={classNames(headingClassName, styles.heading)}>{heading}</span>
          {subheading != null ? (
            <span className={classNames(styles.subheading, subheadingClassName)}>{subheading}</span>
          ) : null}
        </div>
      </H2>
    ),
    [
      headerClassName,
      headerToggleClassName,
      hintId,
      empty,
      onToggle,
      expanded,
      headingClassName,
      heading,
      subheading,
      subheadingClassName,
    ],
  )
  return (
    <div ref={ref} className={classNames(className, styles.panel)}>
      {headerElement}
      {expanded ? (
        <div className={classNames(contentClassName, styles.content)}>{content}</div>
      ) : null}
    </div>
  )
}

export default React.memo(React.forwardRef(ExpandablePanel))
