import Checkbox from '@jetbrains/ring-ui-built/components/checkbox/checkbox'
import {objectValues} from '@jetbrains/teamcity-ui/dist/utils'
import * as React from 'react'
import {Suspense, useCallback} from 'react'
import type {PreloadedQuery} from 'react-relay'
import {useLocation, useNavigate} from 'react-router'

import BuildLineLayout from '../../../../../containers/BuildLineLayout'
import type {State} from '../../../../../reducers/types'
import {getAgentsOverviewHref, getDisconnectedAgentsOverviewHref} from '../../../../../routes'
import {getAgentPreviewsReady, getAllAgentPreviews} from '../../../../../selectors'
import Loader from '../../../../common/Loader/Loader'
import type {AgentsPagesAgentTypesQuery} from '../../__generated__/AgentsPagesAgentTypesQuery.graphql'
import type {AgentsPagesCanViewAgentDetailsFragment$key} from '../../__generated__/AgentsPagesCanViewAgentDetailsFragment.graphql'
import {AgentPagePoolsSubscriber, useAgentPools} from '../../AgentPagePoolsProvider'
import AgentsSortingSelect, {
  useAgentsSortingSelectState,
} from '../../components/AgentsSortingSelect/AgentsSortingSelect'

import {getAllAgentsTab} from './AllAgentsTab.selector'
import ExpandableAgentPoolContainer from './ExpandableAgentPool/ExpandableAgentPool.container'

import styles from './AllAgentsTab.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

type Props = {
  dataKey: AgentsPagesCanViewAgentDetailsFragment$key | null
}
type ContainerProps = Props & {
  agentTypesQueryRef: PreloadedQuery<AgentsPagesAgentTypesQuery>
}
export default function AllAgentsTabContainer(props: ContainerProps) {
  const {agentTypesQueryRef, ...restProps} = props

  return (
    <Suspense>
      <AgentPagePoolsSubscriber agentTypesQueryRef={agentTypesQueryRef}>
        <AllAgentsTab {...restProps} />
      </AgentPagePoolsSubscriber>
    </Suspense>
  )
}

function AllAgentsTab({dataKey}: Props) {
  const ready = useAppSelector(getAgentPreviewsReady)
  const navigate = useNavigate()
  const location = useLocation()

  const showOnlyDisconnected = location.pathname === getDisconnectedAgentsOverviewHref()
  const [agentsSorting, setAgentsSorting] = useAgentsSortingSelectState()

  const onChangeShowOnlyDisconnected = React.useCallback(
    (e: React.SyntheticEvent<HTMLInputElement>) =>
      navigate(
        e.currentTarget.checked ? getDisconnectedAgentsOverviewHref() : getAgentsOverviewHref(),
      ),
    [navigate],
  )

  const registeredAgentsExist = useAppSelector(
    state => objectValues(getAllAgentPreviews(state)).length > 0,
  )
  const pools = useAgentPools()
  const selector = useCallback((state: State) => getAllAgentsTab(state, {pools}), [pools])
  const agentsTreeRootsCount = useAppSelector(state => selector(state).length)

  return ready ? (
    <>
      {registeredAgentsExist ? (
        <>
          <div className={styles.toolbar}>
            <AgentsSortingSelect
              className={styles.sortingSelect}
              onChange={setAgentsSorting}
              selected={agentsSorting}
            />
            <Checkbox checked={showOnlyDisconnected} onChange={onChangeShowOnlyDisconnected}>
              {'Show only disconnected agents'}
            </Checkbox>
          </div>
          <BuildLineLayout showAgent={false} showExactDuration={false} showPath showBranch>
            {Array(agentsTreeRootsCount)
              .fill(null)
              .map((_, index) => (
                <ExpandableAgentPoolContainer
                  // eslint-disable-next-line react/no-array-index-key
                  key={index}
                  index={index}
                  showOnlyDisconnected={showOnlyDisconnected}
                  sortingType={agentsSorting?.value}
                  selector={selector}
                  dataKey={dataKey}
                />
              ))}
          </BuildLineLayout>
        </>
      ) : (
        'No registered agents.'
      )}
    </>
  ) : (
    <Loader />
  )
}
