import {PlaceId} from '@jetbrains/teamcity-ui/dist/plugin'
import classNames from 'classnames'
import compose from 'lodash/flowRight'
import * as React from 'react'

import {withActiveEntityId} from '../../../../hooks/routes'
import type {TabAdapterProps} from '../../ClassicUITabAdapter/ClassicUITabAdapter'
import {useActiveEntities, useCachedPlugins} from '../Plugin.hooks'
import {usePluginsLoader} from '../Plugin.loader'
import styles from '../Plugin.module.css'
import type {DummyPlugin} from '../Plugin.types'
import SakuraUIPlugin from '../SakuraUIPlugin/SakuraUIPlugin'

type OwnProps = TabAdapterProps & {
  readonly css: Array<string>
  readonly js: Array<string>
  readonly url: string

  readonly pluginDevelopmentMode: string | null | undefined
}
function TabPlugin({
  tabId,
  title: name,
  js,
  css,
  url,
  pluginDevelopmentMode,
  ...restProps
}: OwnProps) {
  const placeId = PlaceId.TAB_PLUGIN_CONTAINER
  const activeEntities = useActiveEntities({
    agentId: String(restProps.agentId),
    buildTypeId: restProps.buildTypeId,
    buildId: String(restProps.buildId),
    agentTypeId: String(restProps.agentTypeId),
    projectId: restProps.projectId,
  })
  const showDevelopmentInfo = pluginDevelopmentMode != null
  const pluginsToRender = useCachedPlugins(placeId)

  const availablePlugins = React.useMemo<Array<DummyPlugin>>(
    () => [
      {
        name,
        js,
        css,
        extensionUrl: url,
      },
    ],
    [css, js, name, url],
  )

  usePluginsLoader({
    availablePlugins,
    placeId,
    activeEntities,
    pluginDevelopmentMode,
    availablePluginsLoading: false,
  })

  return (
    <div
      id={placeId}
      title={showDevelopmentInfo ? placeId : undefined}
      className={classNames('placeIdModule', {
        [styles.developmentMode]: showDevelopmentInfo,
      })}
    >
      {showDevelopmentInfo && <span className={styles.positionName}>{placeId}</span>}
      {pluginsToRender.map(pluginName => (
        <SakuraUIPlugin
          name={pluginName}
          placeId={placeId}
          activeEntities={activeEntities}
          key={pluginName}
        />
      ))}
    </div>
  )
}

export default compose(React.memo, withActiveEntityId)(TabPlugin)
