import {memo} from 'react'

import type {AgentPoolId} from '../../../../../../../types'
import AgentPoolFavoriteStar from '../../../../AgentPoolsFavoritePage/Star/AgentPoolFavoriteStar'
import {isAgentPoolId} from '../../../../AgentsPages.utils'
import type {AgentSelectionId} from '../../../../AgentsSidebar/AgentsSidebar.types'
import styles from '../ExpandableAgentPool.module.css'

interface Props {
  id?: AgentPoolId | AgentSelectionId | string
  count: number
}
function ExpandableAgentPoolSubHeading(props: Props) {
  const {count, id} = props
  return (
    <>
      {count > 0 ? count : 'no agents'}
      {isAgentPoolId(id) && <AgentPoolFavoriteStar className={styles.star} id={id} />}
    </>
  )
}

export default memo(ExpandableAgentPoolSubHeading)
