import {useMemo} from 'react'

import {useAppSelector} from '../../../../../../hooks/react-redux'
import type {State} from '../../../../../../reducers/types'
import {stringifyId} from '../../../../../../types'
import type {AgentsPagesCanViewAgentDetailsFragment$key} from '../../../__generated__/AgentsPagesCanViewAgentDetailsFragment.graphql'
import type {
  AgentsTree,
  AgentsTreeAgentNode,
  AgentsTreeAgentTypeNode,
  AgentsTreeRootNodeChild,
} from '../../../AgentsSidebar/AgentsSidebar.types'
import {AgentTreeItemType} from '../../../AgentsSidebar/AgentsSidebar.types'

import ExpandableAgentPool from './ExpandableAgentPool'

type Props = {
  index: number
  showOnlyDisconnected: boolean
  sortingType: string | undefined
  selector: (state: State) => AgentsTree
  dataKey: AgentsPagesCanViewAgentDetailsFragment$key | null
}

function ExpandableAgentPoolContainer({
  index,
  showOnlyDisconnected,
  sortingType,
  selector,
  dataKey,
}: Props) {
  const id = useAppSelector(state => selector(state)[index].id)
  const type = useAppSelector(state => selector(state)[index].type)
  const title = useAppSelector(state => selector(state)[index].title)
  const children = useAppSelector(
    state => selector(state)[index].children,
  ) as AgentsTreeRootNodeChild[]

  const flatChildren = useMemo(
    () =>
      children.filter(child => child.type !== AgentTreeItemType.POOL) as (
        | AgentsTreeAgentNode
        | AgentsTreeAgentTypeNode
      )[],
    [children],
  )

  const reducedChildren = showOnlyDisconnected
    ? flatChildren.flatMap(child => {
        const nextChildren = child.type === AgentTreeItemType.AGENT_TYPE ? child.children : [child]

        return nextChildren.filter(({connected}) => !connected)
      }, [])
    : flatChildren
  const count = reducedChildren.length

  return (showOnlyDisconnected || type === AgentTreeItemType.SELECTION) && count === 0 ? null : (
    <ExpandableAgentPool
      id={id}
      type={type}
      title={title}
      childNodes={reducedChildren}
      count={count}
      key={stringifyId(id)}
      sortingType={sortingType}
      dataKey={dataKey}
    />
  )
}

export default ExpandableAgentPoolContainer
