import {CustomItem, Tabs} from '@jetbrains/ring-ui-built/components/tabs/tabs'
import * as React from 'react'
import {Suspense} from 'react'
import type {EntryPointProps} from 'react-relay'
import {usePreloadedQuery} from 'react-relay'
import {useLocation, useNavigate} from 'react-router'

import {useQueryParam} from '../../../../hooks/routes'
import useDocumentTitle from '../../../../hooks/useDocumentTitle'
import useUpdateLastPage from '../../../../hooks/useUpdateLastPage'
import {getAgentPreviewsArg} from '../../../../rest/agents'
import {getAgentsOverviewHref, getHrefWithQueryParams} from '../../../../routes'
import {getAgentPreviewsReady} from '../../../../selectors'
import {restApi} from '../../../../services/rest'
import type {Tab} from '../../../../types'
import {stringifyId} from '../../../../types'
import {emptyArray} from '../../../../utils/empty'
import {extractError} from '../../../../utils/extractError'
import {LAST_AGENTS_PAGE_KEY} from '../../../../utils/lastPage'
import ClassicUITabAdapter from '../../../common/ClassicUITabAdapter/ClassicUITabAdapter'
import Loader from '../../../common/Loader/Loader'
import OverviewTab, {createClassicUIOverviewTab} from '../../../common/OverviewTab/OverviewTab'
import MammothHint from '../../../common/OverviewTab/OverviewTab.mammoth'
import PageTitle from '../../../common/PageTitle/PageTitle'
import TabPlugin from '../../../common/Plugin/TabPlugin/TabPlugin'
import TabsLoader from '../../../common/TabsLoader/TabsLoader'
import type {AgentsPagesQueries} from '../AgentsPages.queries'

import type {AgentsOverviewPageQuery} from './__generated__/AgentsOverviewPageQuery.graphql'
import {query} from './AgentsOverviewPage.queries'
import AllAgentsTab from './AllAgentsTab/AllAgentsTab'
import AgentsToolbar from './Toolbar/Toolbar'
import useAgentsTabs from './useAgentsTabs'

import styles from './AgentsOverviewPage.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

const ALL_AGENTS_TAB_ID = 'all-agents'

type Queries = AgentsPagesQueries & {main: AgentsOverviewPageQuery}
export default function AgentsOverviewPage({queries}: EntryPointProps<Queries, {}, {}, {}>) {
  const data = usePreloadedQuery(query, queries.main)
  const {
    allTabsReady,
    tabs: {sakuraTabs, classicTabs},
  } = useAgentsTabs()
  const ready = useAppSelector(getAgentPreviewsReady)
  const {agentPreviewsError} = restApi.endpoints.getAllAgentPreviewsNormalized.useQuery(
    getAgentPreviewsArg(),
    {selectFromResult: ({error}) => ({agentPreviewsError: error})},
  )
  const error = extractError(agentPreviewsError)

  useUpdateLastPage(ready, error, LAST_AGENTS_PAGE_KEY, getAgentsOverviewHref())
  useDocumentTitle('Agents Overview — TeamCity')

  const tabParam = useQueryParam('tab', ALL_AGENTS_TAB_ID)
  const location = useLocation()
  const navigate = useNavigate()
  const onSelect = React.useCallback(
    (tab: string) => {
      navigate(
        getHrefWithQueryParams(location, null, () => ({
          tab,
        })),
        {preventScrollReset: true},
      )
    },
    [navigate, location],
  )

  const renderTab = React.useCallback((tab: Tab) => {
    const {id, onlyClassicUI, title, href} = tab

    if (onlyClassicUI) {
      return createClassicUIOverviewTab({id, href, title})
    }

    const Wrapper = tab.sakura === true ? TabPlugin : ClassicUITabAdapter

    return (
      <OverviewTab isClassic key={stringifyId(id)} id={id} title={title} href={href}>
        <Wrapper agents tabId={id} title={title} js={tab?.js} css={tab?.css} url={tab?.url} />
      </OverviewTab>
    )
  }, [])

  const sakuraUITabs = React.useMemo(
    () =>
      [
        <OverviewTab key={ALL_AGENTS_TAB_ID} id={ALL_AGENTS_TAB_ID} title="All Agents">
          <Suspense fallback={<Loader />}>
            <AllAgentsTab agentTypesQueryRef={queries.agentTypes} dataKey={data} />
          </Suspense>
        </OverviewTab>,
      ].concat(sakuraTabs?.map(renderTab) ?? emptyArray),
    [queries.agentTypes, data, sakuraTabs, renderTab],
  )
  const classicUITabs = React.useMemo(
    () => classicTabs?.map(renderTab) ?? emptyArray,
    [classicTabs, renderTab],
  )

  if (!window.GLOBAL_ERROR_PAGE_DISABLED && error != null) {
    throw error
  }

  return (
    <div className={styles.page}>
      <PageTitle>{'Overview'}</PageTitle>
      <AgentsToolbar />
      <Tabs
        selected={tabParam ?? undefined}
        className={styles.tabs}
        onSelect={onSelect}
        initialVisibleItems={3}
        autoCollapse={process.env.NODE_ENV !== 'test'}
        morePopupBeforeEnd={(classicTabs.some(tab => tab.onlyClassicUI) && <MammothHint />) || null}
      >
        {sakuraUITabs}
        {classicUITabs}
        {!allTabsReady ? (
          <CustomItem key="tabs_loader">
            <TabsLoader />
          </CustomItem>
        ) : null}
      </Tabs>
    </div>
  )
}
export type AgentsOverviewPageComponent = typeof AgentsOverviewPage
