import {objectToQuery, resolveRelative} from '@jetbrains/teamcity-ui/dist/utils'
import {useMemo} from 'react'

import type {TabsList, TabProps} from '../../../../hooks/useTabs'
import {getTabsArg} from '../../../../rest/tabs'
import {getAgentsHref} from '../../../../routes'
import {generateClassicUILinkWithQuery} from '../../../../selectors'
import {restApi} from '../../../../services/rest'
import {AGENTS_TAB_PARAMS_KEY, stringifyId} from '../../../../types'
import {emptyArray} from '../../../../utils/empty'

// Tabs from the Classic UI been unified in the Sakura UI
const IGNORE_LIST = [
  'registeredAgents',
  'unregisteredAgents',
  'unauthorizedAgents',
  'agentPools',
  'clouds',
]

// Matrix
const ONLY_CLASSIC_UI_TABS = ['agentsStatisticsTableTab']
const classicUIHref = resolveRelative('/agents.html')
export default function useAgentsTabs(): TabProps {
  const {
    allTabsReady,
    availableTabs,
    refetch: refetchTabs,
  } = restApi.endpoints.getTabs.useQuery(getTabsArg(AGENTS_TAB_PARAMS_KEY), {
    selectFromResult: ({data}) => ({
      allTabsReady: data != null,
      availableTabs: data ?? emptyArray,
    }),
  })
  const tabs: TabsList = useMemo(() => {
    const result = availableTabs
      .filter(({id}) => !IGNORE_LIST.includes(id))
      .reduce(
        (accumulator: TabsList, tab) => {
          const id = tab.id
          const onlyClassicUI = ONLY_CLASSIC_UI_TABS.includes(id)
          const urlParams = {
            tab: stringifyId(id),
          }

          const href = onlyClassicUI
            ? generateClassicUILinkWithQuery(classicUIHref, urlParams)
            : `${getAgentsHref()}?${objectToQuery(urlParams)}`

          const entity = {
            ...tab,
            id,
            href,
          }

          if (onlyClassicUI) {
            entity.onlyClassicUI = true
            accumulator.classicTabs.push(entity)
          } else {
            accumulator.sakuraTabs.push(entity)
          }

          return accumulator
        },
        {classicTabs: [], sakuraTabs: []},
      )
    result.sakuraTabs.sort((tab1, tab2) => (tab1.sakura ? 1 : 0) - (tab2.sakura ? 1 : 0))
    return result
  }, [availableTabs])

  return {
    allTabsReady,
    tabs,
    refetchTabs,
  }
}
